WITH flattened_attrs AS (SELECT id, effective_from, discounts, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ELEMENT_AT(tier_prices, 1) AS entry_price FROM price_tiers WHERE effective_from <= '2024-10-11') SELECT id, effective_from, entry_price, AVG(entry_price) OVER (ORDER BY effective_from, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_avg_entry_price, MIN(entry_price) OVER (ORDER BY effective_from, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_min_entry_price, MAX(entry_price) OVER (ORDER BY effective_from, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_max_entry_price FROM flattened_attrs WHERE entry_price BETWEEN 29 AND 30;
